pub fn captions(s: State) -> Vec<&'static str> {
    vec![match s.region_this_tab_shows { RegionThisTabShows::StateEnterYourWorkEmail => "Enter your work email", RegionThisTabShows::StateCheckYourEmail => "Check your email", RegionThisTabShows::StateSigningYouIn => "Signing you in", RegionThisTabShows::StateThisLinkNoLongerWorks => "This link no longer works", RegionThisTabShows::StateNoAccessToThisPractice => "No access to this practice", RegionThisTabShows::StateYourWorkspace => "Your workspace", RegionThisTabShows::StateSignInPromptOverYourWork => "Sign-in prompt over your work" },
        match s.region_your_session { RegionYourSession::StateSignedOut => "Signed out", RegionYourSession::StateSignedIn => "Signed in", RegionYourSession::StateSessionExpired => "Session expired" },
        match s.region_a_patient_link_this_tab_holds { RegionAPatientLinkThisTabHolds::StateNoPatientLink => "No patient link", RegionAPatientLinkThisTabHolds::StateHoldingAPatientLink => "Holding a patient link" },
        match s.region_where_the_workspace_opens { RegionWhereTheWorkspaceOpens::StateToday => "Today", RegionWhereTheWorkspaceOpens::StateTheLinkedPatient => "The linked patient" }]
}
impl std::fmt::Debug for State {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&captions(*self).join(" · "))
    }
}
pub fn every_state() -> Vec<State> {
    vec![State { region_this_tab_shows: RegionThisTabShows::StateEnterYourWorkEmail, region_your_session: RegionYourSession::StateSignedOut, region_a_patient_link_this_tab_holds: RegionAPatientLinkThisTabHolds::StateNoPatientLink, region_where_the_workspace_opens: RegionWhereTheWorkspaceOpens::StateToday }].into_iter().flat_map(|s| [RegionThisTabShows::StateEnterYourWorkEmail, RegionThisTabShows::StateCheckYourEmail, RegionThisTabShows::StateSigningYouIn, RegionThisTabShows::StateThisLinkNoLongerWorks, RegionThisTabShows::StateNoAccessToThisPractice, RegionThisTabShows::StateYourWorkspace, RegionThisTabShows::StateSignInPromptOverYourWork].map(|v| State { region_this_tab_shows: v, ..s })).collect::<Vec<_>>().into_iter().flat_map(|s| [RegionYourSession::StateSignedOut, RegionYourSession::StateSignedIn, RegionYourSession::StateSessionExpired].map(|v| State { region_your_session: v, ..s })).collect::<Vec<_>>().into_iter().flat_map(|s| [RegionAPatientLinkThisTabHolds::StateNoPatientLink, RegionAPatientLinkThisTabHolds::StateHoldingAPatientLink].map(|v| State { region_a_patient_link_this_tab_holds: v, ..s })).collect::<Vec<_>>().into_iter().flat_map(|s| [RegionWhereTheWorkspaceOpens::StateToday, RegionWhereTheWorkspaceOpens::StateTheLinkedPatient].map(|v| State { region_where_the_workspace_opens: v, ..s })).collect::<Vec<_>>()
}
pub const EVENTS: &[(&str, fn(State, State) -> bool)] = &[
    ("request a sign-in link", event_request_a_sign_in_link),
    ("use another email", event_use_another_email),
    ("open the email button", event_open_the_email_button),
    ("open another physician's sign-in link", event_open_another_physician_s_sign_in_link),
    ("open your own sign-in link", event_open_your_own_sign_in_link),
    ("verification succeeds", event_verification_succeeds),
    ("the link was used or has expired", event_the_link_was_used_or_has_expired),
    ("the link no longer grants access", event_the_link_no_longer_grants_access),
    ("you sign in in another tab", event_you_sign_in_in_another_tab),
    ("the session expires", event_the_session_expires),
    ("sign out", event_sign_out),
    ("close and reopen Coda", event_close_and_reopen_coda),
    ("open a patient link while signed out", event_open_a_patient_link_while_signed_out),
];
pub struct Chart;
impl Model for Chart {
    type State = State;
    type Action = (&'static str, State);
    fn init_states(&self) -> Vec<State> {
        every_state().into_iter().filter(|s| init(*s)).collect()
    }
    fn actions(&self, s: &State, actions: &mut Vec<Self::Action>) {
        for &(event, step) in EVENTS {
            actions.extend(every_state().into_iter().filter(|t| step(*s, *t)).map(|t| (event, t)));
        }
    }
    fn next_state(&self, _: &State, action: Self::Action) -> Option<State> {
        Some(action.1)
    }
    fn format_action(&self, action: &Self::Action) -> String {
        action.0.to_string()
    }
    fn properties(&self) -> Vec<Property<Self>> {
        vec![
            Property::always("WorkspaceAfterSignOut: Sign-out works. (physician A1.5)", |_, s| rule_workspace_after_sign_out(*s)),
            Property::always("WorkspaceAfterExpiry: If the session expires mid-work, a sign-in prompt covers the screen. (physician A1.3)", |_, s| rule_workspace_after_expiry(*s)),
            Property::always("PromptWhileSignedIn: After signing in the physician is exactly where they were. (physician A1.3)", |_, s| rule_prompt_while_signed_in(*s)),
            Property::always("HeldLinkLands: A patient link opened while signed out lands that tab on the patient after sign-in. (physician A1.3)", |_, s| rule_held_link_lands(*s)),
        ]
    }
}
